using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using PaperPixelGames.Core.DressingSceneSystem;using SushiAndFish.Casino;using Object=UnityEngine.Object;
public static class CasinoDetailedFinalVerification {
 public static void VerifyAndAll(){Verify();CityExpansionPlayAudit.DetailedAllGames();}
 [Serializable]public class Building{public string name;public Vector3 min,max;public int meshes;}
 [Serializable]public class Contact{public string protectedObject,collider;public Vector3 point;public float depth;}
 [Serializable]public class Result{public string utc,error;public bool passed;public int coastExpected,coastPresent,coastColliders,parkNpcFurniture;public float coastMaxBoundsError;public List<Building> buildings=new List<Building>();public List<Contact> contacts=new List<Contact>();public List<string> checks=new List<string>();}
 static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 static Bounds VertexBounds(Transform root,out int count){var all=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.gameObject.activeInHierarchy&&f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().enabled);bool init=false;var b=new Bounds();count=0;foreach(var f in all){count++;foreach(var p in f.sharedMesh.vertices){var w=f.transform.TransformPoint(p);if(!init){init=true;b=new Bounds(w,Vector3.zero);}else b.Encapsulate(w);}}return b;}
 public static void Verify(){var q=new Result{utc=DateTime.UtcNow.ToString("o")};try{
  var gs=EditorSceneManager.OpenScene("Assets/SushiAndFish/Modules/OriginalIsland/Scenes/GameState.unity");var ds=EditorSceneManager.OpenScene("Assets/SushiAndFish/Modules/OriginalIsland/Scenes/DressingScenes/100_Dressing_City_01.unity",OpenSceneMode.Additive);var a=Object.FindFirstObjectByType<ParkCasinoIntegration>();
  foreach(var g in gs.GetRootGameObjects().Concat(ds.GetRootGameObjects()).SelectMany(g=>g.GetComponentsInChildren<DressingSceneRoot>(true)))g.ActivateAllImmediate();
  foreach(var root in new[]{a.permanentExterior.transform,gs.GetRootGameObjects().Single(g=>g.name=="CityBuildings_20261021").transform.Find("AR_Restaurant"),gs.GetRootGameObjects().Single(g=>g.name=="CityBuildings_20261021").transform.Find("AR_CinemaLobby")}){int count;var b=VertexBounds(root,out count);q.buildings.Add(new Building{name=root.name,min=b.min,max=b.max,meshes=count});}
  var casinoColliders=a.permanentExterior.GetComponentsInChildren<Collider>(true).Where(c=>!c.isTrigger&&c.gameObject.activeInHierarchy).ToArray();foreach(var c in casinoColliders)c.enabled=true;Physics.SyncTransforms();
  var probe=new GameObject("TemporaryVerificationProbe");var box=probe.AddComponent<BoxCollider>();box.isTrigger=true;
  var seats=Object.FindObjectsByType<EmoteArea>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(s=>s.transform.position.x<-50&&s.transform.position.z>-74&&s.transform.position.z<16).ToArray();
  foreach(var seat in seats){var target=typeof(EmoteArea).GetField("_targetPos",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);var p=(Vector3)target.GetValue(seat);q.checks.Add("PARK_SEAT "+P(seat.transform)+" root="+seat.transform.position+" target="+p);box.size=new Vector3(2.1f,2.2f,2.1f);probe.transform.position=p+Vector3.up*.9f;if(p.sqrMagnitude<1)probe.transform.position=seat.transform.position;
   foreach(var c in casinoColliders)if(c.bounds.Intersects(box.bounds)&&Physics.ComputePenetration(box,probe.transform.position,Quaternion.identity,c,c.transform.position,c.transform.rotation,out var direction,out var depth)&&depth>.015f)q.contacts.Add(new Contact{protectedObject=P(seat.transform),collider=P(c.transform),point=probe.transform.position,depth=depth});
  }
  var rails=gs.GetRootGameObjects().Concat(ds.GetRootGameObjects()).SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.gameObject.activeInHierarchy&&!r.transform.IsChildOf(a.permanentExterior.transform)&&(r.name.StartsWith("SM_fence",StringComparison.OrdinalIgnoreCase)||r.name.StartsWith("SM_wall",StringComparison.OrdinalIgnoreCase))&&r.bounds.max.x<-49&&r.bounds.min.x>-160&&r.bounds.min.z>-80&&r.bounds.max.z<20).ToArray();
  foreach(var rail in rails){var b=rail.bounds;box.size=b.size+Vector3.one*.02f;probe.transform.SetPositionAndRotation(b.center,Quaternion.identity);foreach(var c in casinoColliders)if(c.bounds.Intersects(b)&&Physics.ComputePenetration(box,probe.transform.position,Quaternion.identity,c,c.transform.position,c.transform.rotation,out var direction,out var depth)&&depth>.04f)q.contacts.Add(new Contact{protectedObject=P(rail.transform),collider=P(c.transform),point=b.center,depth=depth});}
  var parkFurniture=gs.GetRootGameObjects().Concat(ds.GetRootGameObjects()).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.StartsWith("BenchWood",StringComparison.OrdinalIgnoreCase)&&t.position.x>-152&&t.position.x<-50&&t.position.z>-74&&t.position.z<16).ToArray();
  foreach(var furniture in parkFurniture){var rs=furniture.GetComponentsInChildren<MeshRenderer>(true);if(rs.Length==0)continue;var b=rs[0].bounds;foreach(var rr in rs.Skip(1))b.Encapsulate(rr.bounds);q.parkNpcFurniture++;box.size=b.size+new Vector3(.10f,.10f,.10f);probe.transform.SetPositionAndRotation(b.center,Quaternion.identity);foreach(var c in casinoColliders)if(c.bounds.Intersects(b)&&Physics.ComputePenetration(box,probe.transform.position,Quaternion.identity,c,c.transform.position,c.transform.rotation,out var direction,out var depth)&&depth>.015f)q.contacts.Add(new Contact{protectedObject=P(furniture),collider=P(c.transform),point=b.center,depth=depth});}
  q.checks.Add("PARK_RAIL_SEGMENTS="+rails.Length);q.checks.Add("DOOR_FRONT="+(Quaternion.Euler(0,a.parkYaw,0)*Vector3.back));q.checks.Add("SHORT_ROAD_REMOVED="+!gs.GetRootGameObjects().Any(g=>g.name=="CasinoFrontRoadOnly"));foreach(var t in Object.FindObjectsByType<Terrain>(FindObjectsInactive.Include,FindObjectsSortMode.None))q.checks.Add("TERRAIN_COLLIDER_DATA_MATCH "+t.name+"="+(t.GetComponent<TerrainCollider>().terrainData==t.terrainData));Object.DestroyImmediate(probe);
  var baseline=JsonUtility.FromJson<TownCoastRestoration20261021.Receipt>(File.ReadAllText(Path.Combine(IslandRevision20261018.Reports,"town-coast-restoration-applied.json")));
  var renderers=gs.GetRootGameObjects().Concat(ds.GetRootGameObjects()).SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();q.coastExpected=baseline.objects.Count;
  foreach(var item in baseline.objects){var candidates=renderers.Where(r=>P(r.transform)==item.path).ToArray();var nearest=candidates.OrderBy(r=>Vector3.Distance(r.bounds.min,item.min)+Vector3.Distance(r.bounds.max,item.max)).FirstOrDefault();if(!nearest){q.checks.Add("MISSING_COAST "+item.source);continue;}float error=Mathf.Max(Vector3.Distance(nearest.bounds.min,item.min),Vector3.Distance(nearest.bounds.max,item.max));q.coastMaxBoundsError=Mathf.Max(q.coastMaxBoundsError,error);if(error<.026f){q.coastPresent++;if(nearest.GetComponents<Collider>().Any(c=>c.enabled&&!c.isTrigger))q.coastColliders++;}else q.checks.Add("COAST_BOUNDS_ERROR "+item.source+"="+error);}
  q.passed=q.contacts.Count==0&&q.buildings.Count==3&&q.coastPresent==q.coastExpected&&q.coastExpected==885&&q.coastColliders==885&&q.parkNpcFurniture==6;
 }catch(Exception e){q.error=e.ToString();}finally{File.WriteAllText(Path.Combine(IslandRevision20261018.Reports,"casino-detailed-final-static.json"),JsonUtility.ToJson(q,true));EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");}}
}
